        $result = ($this->run)(MailSpec::SAVE_CPGREYLIST_CONFIG, [
            'childTimeoutSecs' => $childTimeoutSecs,
            'initialBlockTimeMins' => $initialBlockTimeMins,
            'maxChildProcs' => $maxChildProcs,
            'mustTryTimeMins' => $mustTryTimeMins,
            'purgeIntervalMins' => $purgeIntervalMins,
            'recordExpTimeMins' => $recordExpTimeMins,
            'spfBypass' => $spfBypass,
        ]);

        return $result;
    }
}
